/**
 * Componente: codrops-sticky-grid-scroll-main
 * Responsabile per la formazione a griglia al centro e la separazione
 * durante lo scroll per rivelare il testo al centro.
 */

export const materialDefinition = Object.freeze({
  "slug": "codrops-sticky-grid-scroll-main", 
  "role": "Componente", 
  "sourceRoot": "MOTION_COMPONENTE/ARCHIVIO/codrops-sticky-grid-scroll-main"
});

/**
 * buildGridTimeline
 * Crea la timeline di base in cui la griglia si apre (zoom out / traslazione).
 * @param {Object} scope - il contesto della scena che contiene gsap.
 * @param {Array} images - gli array di layer (layout, motion, reveal, content) di ogni immagine.
 * @param {Element} textBlock - il contenitore dei testi centrali.
 */
export function buildGridTimeline({ scope, images, textBlock }) {
  const { gsap } = scope;
  const tl = gsap.timeline();

  // Diamo per assunto che nel CSS siano tutte impilate al centro.
  // Stato inziale della griglia (compattata al centro)
  // 1: Alto Sinistra, 2: Alto Destra, 3: Basso Sinistra, 4: Basso Destra
  
  const initialPositions = [
    { xPercent: -55, yPercent: -55, scale: 1 },
    { xPercent: 55, yPercent: -55, scale: 1 },
    { xPercent: -55, yPercent: 55, scale: 1 },
    { xPercent: 55, yPercent: 55, scale: 1 }
  ];

  const expandedPositions = [
    { xPercent: -150, yPercent: -100, scale: 1.2 },
    { xPercent: 150, yPercent: -100, scale: 1.2 },
    { xPercent: -150, yPercent: 100, scale: 1.2 },
    { xPercent: 150, yPercent: 100, scale: 1.2 }
  ];

  // Set initial grid formation
  images.forEach((img, i) => {
    gsap.set(img.layout, initialPositions[i]);
  });

  // Animate to expanded formation
  images.forEach((img, i) => {
    tl.to(img.layout, {
      xPercent: expandedPositions[i].xPercent,
      yPercent: expandedPositions[i].yPercent,
      scale: expandedPositions[i].scale,
      ease: "power2.inOut",
    }, 0); // start at same time
  });

  // Reveal texts
  tl.fromTo(textBlock, 
    { autoAlpha: 0, scale: 0.8 }, 
    { autoAlpha: 1, scale: 1, ease: "power2.out" }, 
    0.2 // start slightly after expansion begins
  );

  return tl;
}
