import { misuraScena, preparaLayerAttore } from "../scenografie/scena-001.js";
import * as materiale01 from "../meccaniche/01-codrops-sticky-grid-scroll-main.js";
import * as materiale02 from "../meccaniche/02-codrops-motion-path-transition-main-2.js";
import * as materiale03 from "../meccaniche/03-rotatingonscrollanimations-main.js";

// Conservare soltanto gli import pertinenti a questa scena e chiamarne davvero
// le funzioni in setup. Nel sito completo ogni materiale deve essere usato
// almeno da una scena, non necessariamente da tutte.
export const availableMaterials = Object.freeze({
  "codrops-sticky-grid-scroll-main": materiale01,
  "codrops-motion-path-transition-main-2": materiale02,
  "rotatingonscrollanimations-main": materiale03,
});

export { misuraScena, preparaLayerAttore };
import { pathCoordinates } from "../scenografie/scena-001.js";

export const implementationStatus = "implemented";
export const sceneDefinition = {
  id: "site:01-scena-podere",
  label: "scena-podere",
  selector: "[data-m21-root=\"scene-001\"]",
  fallbackIndex: 0,
  dependencies: ["MotionPathPlugin"],
  setup: function(scope) {
    const { gsap, ScrollTrigger } = scope;
    gsap.registerPlugin(window.MotionPathPlugin);

    // Dichiara quali elementi stiamo gestendo
    const textBlock = scope.one(".testi-scena", ["autoAlpha", "scale"]);
    
    // Associa le immagini ai layer della struttura creata
    const images = [];
    for(let i = 1; i <= 4; i++) {
      images.push(preparaLayerAttore(scope, {
        layout: scope.root.querySelector(`.layout-${i}`),
        motion: scope.root.querySelector(`.motion-${i}`),
        reveal: scope.root.querySelector(`.reveal-${i}`),
        content: scope.root.querySelector(`.content-${i}`)
      }));
    }

    // Setup master timeline.
    const masterTl = gsap.timeline();

    // Seme 1: Introduzione tramite Motion Path
    const introTl = materiale02.buildIntroPathTimeline({
      scope, 
      images, 
      pathData: pathCoordinates
    });
    masterTl.add(introTl, 0);

    // Componente: Timeline legata allo scroll che espande la griglia
    const scrollTl = materiale01.buildGridTimeline({
      scope,
      images,
      textBlock
    });

    // Pinning e scrubbing
    scope.pin({
      distance: () => scope.root.offsetHeight * 2,
      trigger: scope.root,
      start: "top top",
      animation: scrollTl,
      scrub: 1,
      pin: true,
      pinSpacing: true
    });

    // Seme 2: Animazione di rotazione indipendente legata allo scroll
    materiale03.buildRotationEffect({
      scope,
      images,
      triggerElement: scope.root
    });

    // Clean up if needed is handled by Engine API and defer
    return () => {
      // eventuali custom cleanup (GSAP tl kill è handleato da engine se linked properly o on node remove)
    };
  }
};
